import React, { useState } from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { Toaster } from "react-hot-toast";

import PostureStudio from "./pages/PostureStudio";
import WorkoutEngine from "./pages/WorkoutEngine";
import CoachChat from "./pages/CoachChat";
import ProgressAnalytics from "./pages/ProgressAnalytics";

// Sayfaların useOutletContext() bağımlılığını kırmak için sahte bir context taklit ediyoruz
export default function App() {
  const [activeTab, setActiveTab] = useState(window.location.pathname);

  // Sol menüyü (Sidebar) doğrudan buraya entegre ederek sayfaları sağa basıyoruz
  const renderSidebar = () => (
    <aside className="w-64 border-r border-border bg-surface p-4 flex flex-col justify-between shrink-0">
      <div className="space-y-6">
        <div className="px-4 py-2">
          <h1 className="font-display text-xl font-bold bg-gradient-to-r from-primary to-accent bg-clip-text text-transparent">AuraFit AI</h1>
          <p className="text-[10px] text-text-muted uppercase tracking-wider font-semibold">Graduation Project</p>
        </div>
        <nav className="space-y-1">
          <a href="/posture" onClick={() => setActiveTab("/posture")} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === "/posture" ? "bg-primary/10 text-primary border border-primary/20" : "text-text-secondary hover:text-text-primary hover:bg-card"}`}>
            📸 Posture Studio
          </a>
          <a href="/workout" onClick={() => setActiveTab("/workout")} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === "/workout" ? "bg-primary/10 text-primary border border-primary/20" : "text-text-secondary hover:text-text-primary hover:bg-card"}`}>
            🏋️ AI Workout Engine
          </a>
          <a href="/coach" onClick={() => setActiveTab("/coach")} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === "/coach" ? "bg-primary/10 text-primary border border-primary/20" : "text-text-secondary hover:text-text-primary hover:bg-card"}`}>
            💬 FitCoach Chat
          </a>
          <a href="/progress" onClick={() => setActiveTab("/progress")} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === "/progress" ? "bg-primary/10 text-primary border border-primary/20" : "text-text-secondary hover:text-text-primary hover:bg-card"}`}>
            📊 Progress Analytics
          </a>
        </nav>
      </div>
      <div className="p-3 border-t border-border flex items-center gap-2">
        <div className="w-2 h-2 rounded-full bg-accent animate-pulse" />
        <span className="text-[11px] text-text-muted">System Synchronized</span>
      </div>
    </aside>
  );

  return (
    <BrowserRouter>
      <Toaster position="top-right" />
      <div className="flex min-h-screen bg-base text-text-primary">
        {renderSidebar()}
        <main className="flex-1 overflow-y-auto h-screen">
          <Routes>
            <Route path="/posture" element={<PostureStudio />} />
            <Route path="/workout" element={<WorkoutEngine />} />
            <Route path="/coach" element={<CoachChat />} />
            <Route path="/progress" element={<ProgressAnalytics />} />
            <Route path="*" element={<Navigate to="/posture" replace />} />
          </Routes>
        </main>
      </div>
    </BrowserRouter>
  );
}
